const dictionaries: Record<Exclude<Locale, "cs">, Record<string, string>> = { en, uk };

export function t(locale: Locale, value: string): string {
  if (locale === "cs") return value;
  return dictionaries[locale][value] ?? value;
}

export function localizeDeep<T>(value: T, locale: Locale): T {
  if (locale === "cs") return value;
  if (typeof value === "string") return t(locale, value) as T;
  if (Array.isArray(value)) return value.map((item) => localizeDeep(item, locale)) as T;
  if (value && typeof value === "object") {
    return Object.fromEntries(
      Object.entries(value as Record<string, unknown>).map(([key, item]) => [key, localizeDeep(item, locale)]),
    ) as T;
  }
  return value;
}

export function withLocale(href: string, locale: Locale): string {
  if (locale === "cs") return href;
  const [path, hash] = href.split("#");
  const separator = path.includes("?") ? "&" : "?";
  return `${path}${separator}lang=${locale}${hash ? `#${hash}` : ""}`;
}
